/**
 * Brand marks for ACP agents, taken from the ACP registry icons
 * (cdn.agentclientprotocol.com/registry/v1/latest). Monochrome on purpose:
 * every path uses currentColor, so the marks follow the app theme.
 *
 * Generated file - don't hand-edit the path data.
 */
import type { ReactNode, SVGProps } from 'react';

type MarkProps = Omit<SVGProps<SVGSVGElement>, 'viewBox' | 'children' | 'width' | 'height'> & { size?: number };

function Mark({ size = 16, viewBox, children, ...rest }: MarkProps & { viewBox: string; children: ReactNode }) {
  return (
    <svg width={size} height={size} viewBox={viewBox} fill="none" focusable="false" aria-hidden {...rest}>
      {children}
    </svg>
  );
}

